import { decorateIndexModel } from './decorateIndexModel';
import type { ManageIndexesApi } from '../../pinecone-generated-ts-fetch/db_control';
import { X_PINECONE_API_VERSION } from '../../pinecone-generated-ts-fetch/db_control';
import { PineconeArgumentError } from '../../errors';
import { handleApiError } from '../../errors/handling';
import type { IndexModel } from './listIndexes';

/**
 * Describes an index by name.
 *
 */
export async function describeIndex(
  api: ManageIndexesApi,
  indexName: string,
): Promise<IndexModel> {
  if (!indexName) {
    throw new PineconeArgumentError(
      'You must pass a non-empty string for `indexName` in order to describe an index.',
    );
  }

  try {
    return decorateIndexModel(
      await api.describeIndex({
        indexName,
        xPineconeApiVersion: X_PINECONE_API_VERSION,
      }),
    );
  } catch (e) {
    throw await handleApiError(
      e,
      async (_, rawMessageText) =>
        `Error describing index ${indexName}: ${rawMessageText}`,
    );
  }
}
